import{bV as r,aL as d,u as a,G as e}from"./chunks/framework.DT-LCgF3.js";const g=JSON.parse('{"title":"RAG 完整链路与架构选型（10）结语","description":"","frontmatter":{"date":"2026-11-25T14:00:00.000Z","title":"RAG 完整链路与架构选型（10）结语","permalink":"/pages/rag10","categories":["AI","RAG"]},"headers":[],"relativePath":"AI/02.RAG/完整链路与架构选型/10.结语.md","filePath":"AI/02.RAG/完整链路与架构选型/10.结语.md","lastUpdated":1795655557000}'),o={name:"AI/02.RAG/完整链路与架构选型/10.结语.md"};function n(s,t,l,h,i,p){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="rag-完整链路与架构选型-10-结语" tabindex="-1">RAG 完整链路与架构选型（10）结语 <a class="header-anchor" href="#rag-完整链路与架构选型-10-结语" aria-label="Permalink to &quot;RAG 完整链路与架构选型（10）结语&quot;">​</a></h1><h2 id="十、结语" tabindex="-1">十、结语 <a class="header-anchor" href="#十、结语" aria-label="Permalink to &quot;十、结语&quot;">​</a></h2><h3 id="_10-1-全链路决策速查" tabindex="-1">10.1 全链路决策速查 <a class="header-anchor" href="#_10-1-全链路决策速查" aria-label="Permalink to &quot;10.1 全链路决策速查&quot;">​</a></h3><p>把全文的结论压缩成一张表。<strong>下表的数值是起点建议，不是普适最优值</strong>——它们的作用是让你有个可调试的初始配置，而不是替你完成调优。任何参数都应在你自己的语料上验证后再定稿。</p><table tabindex="0"><thead><tr><th>环节</th><th>建议起点</th><th>什么时候需要升级</th><th>主要代价</th></tr></thead><tbody><tr><td>解析</td><td>保留结构信息（标题层级、表格边界、代码围栏）的解析器</td><td>表格、代码、层级结构检索不准</td><td>实现复杂度上升</td></tr><tr><td>切分</td><td>结构感知切分；正文块 400–800 token；适度 overlap</td><td>长文档答不全，或单块噪声过大</td><td>需按文档格式分别适配</td></tr><tr><td>向量化</td><td>中文/多语言场景从 bge-m3 起步（1024 维、8192 长度、MIT）；需要更长上下文或更高检索质量时考虑更大模型</td><td>单块长度超过模型上限，或需要多模态</td><td>显存占用与计算成本</td></tr><tr><td>索引</td><td>中小规模用 HNSW；规模上去后考虑 IVF-PQ 或 DiskANN</td><td>内存成本过高，或延迟不达标</td><td>量化带来精度损失，需实测</td></tr><tr><td>召回</td><td>混合检索（稀疏 + 稠密）并用 RRF 融合</td><td>编号类、专有名词查询命中差，或整体漏召回</td><td>需维护两套索引</td></tr><tr><td>重排</td><td>Cross-Encoder 精排，K1 取数十、K2 取个位数</td><td>召回已足够准时，重排收益趋近于零</td><td>GPU 算力与延迟</td></tr><tr><td>生成</td><td>约束式 Prompt + 引用标注 + 拒答设计</td><td>仍出现无依据作答，或引用对不上</td><td>token 成本随 K3 与片段长度上升</td></tr></tbody></table><h3 id="_10-2-三条容易被忽略的原则" tabindex="-1">10.2 三条容易被忽略的原则 <a class="header-anchor" href="#_10-2-三条容易被忽略的原则" aria-label="Permalink to &quot;10.2 三条容易被忽略的原则&quot;">​</a></h3><p>走到这里，全文的技术细节可以忘掉大半，但这三条值得记住：</p><p><strong>其一，离线链路的产出质量决定了在线链路的上限。</strong> 解析丢掉的表格结构、切分切断的语义单元、没写进元数据的权限字段——这些缺陷在后面的召回、重排、生成环节都没有办法补救。检索单元里不存在的信息，没有任何重排模型能从排名里恢复出来。所以当效果不理想时，先回头检查数据侧，而不是急着换更大的模型。</p><p><strong>其二，按成本递增的顺序投入。</strong> 切分策略和混合检索几乎不增加推理成本，却能带来明显的质量提升；重排和更大的生成模型则要消耗显著的算力或 token。先在前者上把质量做够，再考虑后者。顺序反了，容易花了大成本却收效甚微——而且因为缺少评估手段，你甚至不会发现它是负收益。</p><p><strong>其三，没有评估就没有优化。</strong> &quot;感觉回答变好了&quot;不是工程判据。建一个绑定语料版本的离线评估集，同时观测检索侧和生成侧指标，才能判断一次改动到底是优化还是退化。这也是本文把评估单独成章的原因。</p><h3 id="_10-3-一句话总结" tabindex="-1">10.3 一句话总结 <a class="header-anchor" href="#_10-3-一句话总结" aria-label="Permalink to &quot;10.3 一句话总结&quot;">​</a></h3><blockquote><p><strong>离线求全——切得准、存得全；在线求准——捞得广、筛得精、答得稳。</strong></p></blockquote><ul><li><strong>切得准</strong>：解析保留结构，切分贴合语义单元。</li><li><strong>存得全</strong>：向量、原文、元数据、权限一并落库。</li><li><strong>捞得广</strong>：多路召回，宁可多捞不漏。</li><li><strong>筛得精</strong>：重排精挑，把有限的上下文预算留给最相关的片段。</li><li><strong>答得稳</strong>：约束生成，给出来源，不知道就说不知道。</li></ul><h3 id="_10-4-延伸阅读" tabindex="-1">10.4 延伸阅读 <a class="header-anchor" href="#_10-4-延伸阅读" aria-label="Permalink to &quot;10.4 延伸阅读&quot;">​</a></h3><p>本文聚焦工程实现与选型决策，以下站内文章可作为背景补充：</p><table tabindex="0"><thead><tr><th>主题</th><th>文章</th></tr></thead><tbody><tr><td>RAG 的基本概念与五个核心环节</td><td><a href="./../RAG工作机制详解">RAG 工作机制详解</a></td></tr><tr><td>AI 领域整体概念关系</td><td><a href="./../../01.核心概念">AI 核心概念大串联</a></td></tr><tr><td>向量相似度的数学基础（余弦、内积）</td><td><a href="./../../09.向量基础/点积-模长-余弦相似度">点积、模长、余弦相似度</a></td></tr><tr><td>生成阶段的采样参数调节</td><td><a href="./../../07.采样参数/Temperature与Top-p与Top-K">Temperature、Top-p 与 Top-K</a></td></tr><tr><td>Prompt 中的示例设计</td><td><a href="./../../08.提示学习/Zero-shot与Few-shot">Zero-shot 与 Few-shot</a></td></tr><tr><td>本地私有化部署模型</td><td><a href="./../../05.Ollama/Ollama本地部署">Ollama 本地部署</a></td></tr></tbody></table><hr><p><strong>最后一点提醒</strong>：本文引用的所有榜单分数、官方参数与定价都附有来源和查看日期。RAG 领域的技术栈更新很快——模型在迭代、产品能力在变化、定价会调整。把本文当作一套<strong>判断框架和决策依据</strong>，而不是一份长期有效的参数速查表。任何关键参数在采纳前，都值得回到官方来源确认一次当前状态。</p><hr>',19)])])}const c=r(o,[["render",n]]);export{g as __pageData,c as default};
